export const meta = {
  "slug": "heroicons-information-circle",
  "family": "heroicons",
  "name": "information-circle",
  "category": "Interface",
  "motion": "pop",
  "component": "createHeroiconsInformationCircleIcon"
};

export function createHeroiconsInformationCircleIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
